    int m=0;
    for (int i=0;i<n;i++) m=max(m,(a[i]&(-a[i])));

    if (connected(n))
    {
        cout<<ans<<"\n";
        for (int i=0;i<n;i++) cout<<a[i]<<" "; cout<<"\n";
        goto kraj;
    }

    for (int i=0;i<n;i++)
    {
        a[i]--;
        if (connected(n))
        {
            cout<<ans+1<<"\n";
            for (int i=0;i<n;i++) cout<<a[i]<<" "; cout<<"\n";
            goto kraj;
        }
        a[i]++;
    }

    for (int i=0;i<n;i++)
    {
        a[i]++;
        if (connected(n))
        {
            cout<<ans+1<<"\n";
            for (int i=0;i<n;i++) cout<<a[i]<<" "; cout<<"\n";
            goto kraj;
        }
        a[i]--;
    }

    for (int i=0;i<n;i++) if ((a[i]&-a[i])==m)
    {
        a[i]--;
        break;
    }
    for (int i=0;i<n;i++) if ((a[i]&-a[i])==m)
    {
        a[i]++;
        break;
    }

    cout<<ans+2<<"\n";
